195	fn is_at_scss_interpolated_query_feature_value(p: &mut CssParser) -> bool {
196	    if !CssSyntaxFeatures::Scss.is_supported(p) || !is_at_scss_interpolation(p) {
197	        return false;
198	    }
199	
200	    let checkpoint = p.checkpoint();
201	    parse_scss_regular_interpolation(p).ok();
202	    let continues_as_identifier = is_at_scss_interpolated_identifier(p);
203	    p.rewind(checkpoint);
204	
205	    continues_as_identifier
206	}
